    /// Each prompt's editor is as tall as its prompt, growing as lines are
    /// added, so the whole prompt shows and only the page scrolls.
    #[gpui_kit::test]
    async fn prompt_editors_grow_to_fit(cx: &mut TestAppContext) {
        let dir = std::env::temp_dir().join(format!("suspense-settings-grow-{}", std::process::id()));
        fs::remove_dir_all(&dir).ok();
        fs::create_dir_all(&dir).unwrap();
        cx.update(|cx| {
            gpui_kit::init(cx);
            piton_syntax::init();
            ProjectDirectory::init(cx);
            ProjectDirectory::set(dir.clone(), cx);
        });
        let mut settings = None;
        let window = cx.add_window(|window, cx| {
            let view = cx.new(|cx| SettingsWindow::new(window, cx));
            settings = Some(view.clone());
            Root::new(view, window, cx)
        });
        let settings = settings.unwrap();
        let cx = &mut VisualTestContext::from_window(window.into(), cx);
        cx.run_until_parked();
        let height = |cx: &mut VisualTestContext| {
            cx.update(|window, cx| {
                window.refresh();
                let _ = cx;
            });
            cx.run_until_parked();
            settings.update_in(cx, |this, window, cx| {
                let prompt = &this.prompts[0];
                prompt.fit.heights(&prompt.editor, window, cx).0
            })
        };
        let short = {
            settings.update_in(cx, |this, window, cx| {
                this.prompts[0].editor.update(cx, |editor, cx| editor.set_value("one", window, cx))
            });
            height(cx)
        };
        settings.update_in(cx, |this, window, cx| {
            let long = (0..40).map(|n| format!("line {n}")).collect::<Vec<_>>().join("\\n");
            this.prompts[0].editor.update(cx, |editor, cx| editor.set_value(long, window, cx))
        });
        let tall = height(cx);
        assert!(tall > short * 20., "{tall:?} isn't forty lines tall, next to {short:?}");
        fs::remove_dir_all(&dir).ok();
    }
}
